def _authenticated_native_bundle(bundle):
    from astrid.core.timeline.authoring_bundle import compile_authoring_candidate
    from astrid.sdk.timeline.commit import _manifest

    publication = compile_authoring_candidate(bundle).publication
    document = {
        'schema_version': 1,
        'project_id': publication['project_id'],
        'timeline_id': publication['timeline_id'],
        'parent_revision': {
            'revision_id': publication['parent_revision_id'],
            'content_digest': publication['content_digest'],
            'payload': publication['parent_composition'],
        },
        'shot_revisions': publication['shot_revisions'],
        'internal_timeline_revisions': publication['internal_timeline_revisions'],
        'dependency_manifest': _manifest(
            publication['shot_revisions'], publication['internal_timeline_revisions'],
            publication['dependency_manifest']['media'], []),
    }
    return bundle_from_document(document)


@pytest.fixture(autouse=True)
def _use_authenticated_native_bundle(monkeypatch):
    from tests.editing_conformance import test_step_undo_v2

    original = test_step_undo_v2.original
    entry = test_step_undo_v2.entry
    monkeypatch.setattr(test_step_undo_v2, 'original',
                        lambda: _authenticated_native_bundle(original()))

    def authenticated_entry(before, plan, *args, **kwargs):
        result = entry(before, plan, *args, **kwargs)
        after = bundle_from_document(document_from_bundle(result['after']))
        after_document = after['source_mapping']['_runtime_document']
        occurrences = {
            row['occurrence_id']: row
            for row in after_document['parent_revision']['payload']['occurrences']
        }
        shots = {row['shot_id']: row for row in after_document['shot_revisions']}
        internals = {row['revision_id']: row for row in after_document['internal_timeline_revisions']}
        before_rows = copy.deepcopy(
            before['source_mapping']['_runtime_document']['parent_revision']['payload']['occurrences'])
        for step in result['records']['steps']:
            created = [result['records']['commands'][ordinal]['created']
                       for ordinal in step['command_ordinals']]
            created = [item for group in created for item in group]
            created_shots = [item for item in created if item['kind'] == 'shot']
            created_occurrences = [item for item in created if item['kind'] == 'occurrence']
            if created_shots or created_occurrences:
                patches = []
                for item in created_shots:
                    shot = shots[item['ref'].split(':', 1)[1]]
                    patches.append({'op': 'set', 'ref': 'internal-revision:'
                                    + shot['internal_timeline_revision_id'], 'path': [],
                                    'before': {'state': 'absent'},
                                    'value': copy.deepcopy(internals[shot['internal_timeline_revision_id']]['payload'])})
                    patches.append({'op': 'set', 'ref': 'shot-revision:' + shot['revision_id'], 'path': [],
                                    'before': {'state': 'absent'},
                                    'value': {**copy.deepcopy(shot['payload']),
                                              'internal_timeline_revision_id':
                                              shot['internal_timeline_revision_id']}})
                next_rows = copy.deepcopy(before_rows)
                for item in created_occurrences:
                    occurrence = occurrences[item['ref'].split(':', 1)[1]]
                    next_rows.append(copy.deepcopy(occurrence))
                patches.append({'op': 'set', 'ref': 'parent', 'path': ['occurrences'],
                                'before': {'state': 'present', 'value': before_rows},
                                'value': next_rows})
                step['patch'] = patches
                before_rows = next_rows
            elif any(patch['ref'].startswith(('shot:', 'occurrence:'))
                     and not patch['path'] for patch in step['patch']):
                before_document = document_from_bundle(before)
                after_document = document_from_bundle(result['after'])
                before_shots = {row['revision_id']: row for row in before_document['shot_revisions']}
                after_shots = {row['revision_id']: row for row in after_document['shot_revisions']}
                before_internals = {row['revision_id']: row
                                    for row in before_document['internal_timeline_revisions']}
                after_internals = {row['revision_id']: row
                                   for row in after_document['internal_timeline_revisions']}
                patches = []
                for revision_id in sorted(set(before_internals) | set(after_internals)):
                    old, new = before_internals.get(revision_id), after_internals.get(revision_id)
                    if old == new:
                        continue
                    patches.append({'op': 'set' if new else 'remove',
                                    'ref': 'internal-revision:' + revision_id, 'path': [],
                                    'before': ({'state': 'present', 'value': old['payload']}
                                               if old else {'state': 'absent'}),
                                    **({'value': new['payload']} if new else {})})
                for revision_id in sorted(set(before_shots) | set(after_shots)):
                    old, new = before_shots.get(revision_id), after_shots.get(revision_id)
                    if old == new:
                        continue
                    patches.append({'op': 'set' if new else 'remove',
                                    'ref': 'shot-revision:' + revision_id, 'path': [],
                                    'before': ({'state': 'present', 'value': old['payload']}
                                               if old else {'state': 'absent'}),
                                    **({'value': {**new['payload'],
                                                  'internal_timeline_revision_id':
                                                  new['internal_timeline_revision_id']}}
                                       if new else {})})
                old_rows = before_document['parent_revision']['payload']['occurrences']
                new_rows = after_document['parent_revision']['payload']['occurrences']
                patches.append({'op': 'set', 'ref': 'parent', 'path': ['occurrences'],
                                'before': {'state': 'present', 'value': old_rows},
                                'value': new_rows})
                step['patch'] = patches
            for patch in step['patch']:
                if patch['ref'].startswith('occurrence:') and 'value' in patch:
                    patch['value'] = copy.deepcopy(occurrences[patch['ref'].split(':', 1)[1]])
        result['after'] = after
        return result

    monkeypatch.setattr(test_step_undo_v2, 'entry', authenticated_entry)


