@pytest.fixture
def captured():
    assert hashlib.sha256(_CAPTURE.encode()).hexdigest() == (
        '9a47bb934b879efa0f6147d673038cee76299ba4e30ab22b6d5bcb1377ade589')
    return json.loads(_CAPTURE)


def replay(captured):
    before = captured['before']
    entry = before['history']['items'][-1]
    connection = sqlite3.connect(':memory:')
    try:
        connection.executescript('\n'.join(before['database']))
        documents = [json.loads(row[0])['canonical_document'] for row in connection.execute(
            "SELECT result_json FROM command_idempotency WHERE command_kind='timeline.commit'")]
        assert list(connection.iterdump()) == before['database']
    finally:
        connection.close()
    documents = {doc['parent_revision']['revision_id']: doc for doc in documents}
    bundle = bundle_from_document(before['document'])

    def boundary(source):
        return tuple(bundle_from_document(documents[revision]) for revision in (
            source['previous']['revision_id'], source['revision_id']))

    history = {item['publication_id']: item for item in before['history']['items']}
    resolver = inverse_address_resolver([entry], bundle, load_boundary=boundary,
                                        load_history=history.__getitem__)
    records = select_inverse_records(AcceptedRecords(
        [entry], entry['records']['commands'], boundary), address_resolver=resolver)
    return bundle, records


def test_captured_nested_redo_compiles_and_partitions_without_rewriting_source(captured):
    original = copy.deepcopy(captured)
    bundle, records = replay(captured)
    request = captured['request']['body']
    plan = execute(bundle, request['commands'], inverse_records=records,
                   commit_request=request, evaluated_head=captured['before']['history']['head'])
    sources = [source for entry in records.entries for source in records.load_boundary(entry)]
    assert document_from_bundle(plan.bundle, source_bundles=sources) == captured['expected_document']
    assert len(plan.steps) == 1
    assert plan.steps[0]['id'] == 'redo-0'
    assert plan.steps[0]['command_ordinals'] == [0]
    stages = [binding['boundary'] for binding in plan.records[0]['bindings']
              if binding['key'] == 'inverse.stage']
    assert [(stage['native_write_range'], stage['effect_range']) for stage in stages] == [
        ([0, 2], [0, 4]), ([2, 3], [4, 9])]
    assert all((stage['publication_id'], stage['step_id'], stage['command_ordinals']) == (
        request['base_publication_id'], 'undo-0', [0]) for stage in stages)
    source = records.entries[0]
    assert source['publication_id'] == request['base_publication_id']
    assert source['revision_id'] == request['base_revision_id']
    assert plan.records[0]['writes'] == [
        {**write, 'before': write['after'], 'after': write['before']}
        for write in reversed(records[0]['writes'])]
    assert plan.steps[0]['patch'] == inverse_changes(source['records']['steps'][0]['patch'])
    assert not any(binding['key'] == 'commit.materialization' for binding in plan.records[0]['bindings'])
    assert bundle == replay(captured)[0]
    source_bindings = records[0]['bindings']
    assert sum(binding['key'] == 'commit.effect' for binding in plan.records[0]['bindings']) == sum(
        binding['key'] == 'commit.effect' for binding in source_bindings)
    for binding in plan.records[0]['bindings']:
        if binding['key'] != 'commit.effect':
            continue
        expected = next(item for item in source_bindings if item['key'] == 'commit.effect'
                        and item['effect_ordinal'] == 8 - binding['effect_ordinal']
                        and item['boundary']['side'] != binding['boundary']['side'])
        for key in ('physical_ref', 'revision_id', 'content_digest', 'owner', 'owners'):
            assert binding.get(key) == expected.get(key)
        assert binding['step_id'] == 'redo-0'
        assert binding['boundary']['base_publication_id'] == request['base_publication_id']
        assert binding['boundary']['base_revision_id'] == request['base_revision_id']
    assert captured == original


def test_captured_groups_keep_exact_native_source_slices(captured):
    _, records = replay(captured)
    groups = list(inverse_stages(records))
    original = records[0]
    assert len(groups) == 2
    assert [group[2][0]['writes'] for group in groups] == [
        original['writes'][1:3], original['writes'][0:1]]


@pytest.mark.parametrize('mutation', [
    'native-gap', 'native-overlap', 'effect-gap', 'effect-overlap', 'foreign-publication',
    'missing-effect-range', 'missing-all-effect-ranges',
])
def test_captured_nested_ranges_refuse_tampering_without_mutation(captured, mutation):
    entry = captured['before']['history']['items'][-1]
    record = entry['records']['commands'][0]
    stages = [binding['boundary'] for binding in record['bindings'] if binding['key'] == 'inverse.stage']
    if mutation == 'native-gap':
        stages[1]['native_write_range'][0] = 2
    elif mutation == 'native-overlap':
        stages[1]['native_write_range'][0] = 0
    elif mutation == 'effect-gap':
        stages[1]['effect_range'][0] = 6
    elif mutation == 'effect-overlap':
        stages[1]['effect_range'][0] = 4
    elif mutation == 'missing-effect-range':
        del stages[1]['effect_range']
    elif mutation == 'missing-all-effect-ranges':
        for stage in stages:
            del stage['effect_range']
    else:
        stages[1]['publication_id'] = 'foreign-publication'
    original = copy.deepcopy(captured)
    with pytest.raises(CommandError, match='nested inverse ranges differ'):
        list(inverse_stages(AcceptedRecords([entry], [record], None)))
    assert captured == original


@pytest.mark.parametrize('mutation', ['owner', 'source-digest', 'source-scope', 'effect'])
def test_captured_nested_execution_refuses_tampering_without_mutation(captured, mutation):
    if mutation == 'effect':
        entry = captured['before']['history']['items'][-1]
        entry['records']['steps'][0]['patch'][0]['value']['opaque_timeline']['future_schema'] = 10
        original = copy.deepcopy(captured)
        with pytest.raises(CommandError):
            replay(captured)
        assert captured == original
        return
    bundle, records = replay(captured)
    if mutation == 'owner':
        bundle['placements'][0]['shot_id'] = bundle['placements'][1]['shot_id']
    else:
        boundary = records.load_boundary

        def changed(entry):
            before, after = boundary(entry)
            document = before['source_mapping']['_runtime_document']
            if mutation == 'source-digest':
                document['shot_revisions'][0]['content_digest'] = 'sha256:' + '0' * 64
            else:
                document['project_id'] = 'foreign-project'
            return before, after

        records.load_boundary = changed
    original = copy.deepcopy((bundle, captured))
    request = captured['request']['body']
    with pytest.raises((CommandError, ValueError)):
        execute(bundle, request['commands'], inverse_records=records,
                commit_request=request, evaluated_head=captured['before']['history']['head'])
    assert (bundle, captured) == original


@pytest.mark.parametrize('creation', [False, True], ids=['one-of-ten-notes', 'semantic-creation'])
def test_native_only_accepted_inverse_redoes_without_effect_facts(creation):
    from tests.editing_conformance.test_recipe_m1_commands import clip, inverse
    from tests.editing_conformance.test_step_undo_v2 import (
        accepted,
        entry,
        note,
        original,
        selected,
    )

    before = original()
    calls = ([{'schema_version': 1, 'op': 'occurrence.create', 'version': '1', 'select': 'parent',
               'args': {'occurrence_id': f'new-{i}', 'shot_id': f'shot-{i}', 'name': f'Shot {i}',
                        'track': 'picture', 'on': 30 + i * 3, 'duration': 2}} for i in range(2)]
             if creation else [note(f'n{i}', 'B') for i in range(10)])
    plan = execute(before, calls)
    target = entry(before, plan)
    undone = inverse(plan.bundle, selected([target], {'p1': ['s1' if creation else 's3']}))
    if creation:
        assert 'shot-0' in undone.bundle['shots']
        assert 'shot-1' not in undone.bundle['shots']
    else:
        assert clip(undone.bundle)['params'] == {f'n{i}': 'A' if i == 3 else 'B' for i in range(10)}
    stages = [binding for binding in undone.records[0]['bindings'] if binding['key'] == 'inverse.stage']
    assert stages and all('effect_range' not in binding['boundary'] for binding in stages)
    records = accepted([entry(plan.bundle, undone, 'p2', 'p1')])
    snapshot = copy.deepcopy((records.entries, undone.bundle))
    groups = list(inverse_stages(records))
    assert len(groups) == 1
    assert all('_inverse_effects' not in command for command in groups[0][2])
    assert inverse(undone.bundle, records).bundle == plan.bundle
    assert (records.entries, undone.bundle) == snapshot


@pytest.mark.parametrize('mutation', [
    'wrong-step', 'wrong-ordinal', 'negative-ordinal', 'out-of-bounds-ordinal',
    'reordered-ordinals', 'extra-ordinal',
])
def test_captured_nested_identity_must_match_original_accepted_source(captured, mutation):
    history = captured['before']['history']['items']
    entry = history[-1]
    record = entry['records']['commands'][0]
    stages = [binding['boundary'] for binding in record['bindings'] if binding['key'] == 'inverse.stage']
    source = next(item for item in history if item['publication_id'] == stages[0]['publication_id'])
    original_step = next(step for step in source['records']['steps'] if step['id'] == stages[0]['step_id'])
    other_step = next(step for step in source['records']['steps'] if step['id'] != original_step['id'])
    assert stages[0]['command_ordinals'] == original_step['command_ordinals']
    if mutation == 'wrong-step':
        stages[0]['step_id'] = other_step['id']
    elif mutation == 'wrong-ordinal':
        stages[0]['command_ordinals'] = other_step['command_ordinals'][:]
    elif mutation == 'negative-ordinal':
        stages[0]['command_ordinals'] = [-1]
    elif mutation == 'out-of-bounds-ordinal':
        stages[0]['command_ordinals'] = [len(source['records']['commands'])]
    elif mutation == 'reordered-ordinals':
        stages[0]['command_ordinals'] = list(reversed(range(len(source['records']['commands']))))
    else:
        stages[0]['command_ordinals'].append(len(source['records']['commands']))
    snapshot = copy.deepcopy(captured)
    try:
        with pytest.raises(CommandError):
            bundle, records = replay(captured)
            original_bundle = copy.deepcopy(bundle)
            list(inverse_stages(records))
            assert bundle == original_bundle
    finally:
        assert captured == snapshot


@pytest.mark.parametrize('mutation', ['missing-stage', 'extra-effect', 'extra-history'])
def test_captured_nested_requires_complete_source_history(captured, mutation):
    entry = captured['before']['history']['items'][-1]
    record = entry['records']['commands'][0]
    stages = [binding for binding in record['bindings'] if binding['key'] == 'inverse.stage']
    if mutation == 'missing-stage':
        record['bindings'].remove(stages[-1])
    elif mutation == 'extra-effect':
        entry['records']['steps'][0]['patch'].append(copy.deepcopy(entry['records']['steps'][0]['patch'][-1]))
        stages[-1]['boundary']['effect_range'][1] += 1
    else:
        extra = copy.deepcopy(record)
        extra['ordinal'] = 1
        entry['records']['commands'].append(extra)
    snapshot = copy.deepcopy(captured)
    try:
        with pytest.raises(CommandError):
            _, records = replay(captured)
            list(inverse_stages(records))
    finally:
        assert captured == snapshot


@pytest.mark.integration
def test_real_provider_supplies_authenticated_history_lookup(saved_source, tmp_path, monkeypatch):
    from runtime_protocol.errors import RuntimeErrorBase
    from runtime_protocol.timeline_commit_port import RequestCommitPort

    from astrid.sdk.timeline import _commit_patch
    from tests.editing_conformance.test_doc_patch_sequential_rebase import dump, setup

    client, project, document, send, request, _ = setup(saved_source, declared=False)
    original = send(project, 't', request, idempotency_key='original')
    source_publication = original['receipt']['receipt_id']
    history = client.timelines.history(project, 't', limit=100).data
    head = history['head']
    canonical = copy.deepcopy(document('t'))
    before = dump(tmp_path)
    observed = []
    resolve = _commit_patch.inverse_address_resolver

    def capture(entries, bundle, *, load_boundary, load_history=None):
        assert load_history is not None
        assert isinstance(load_history.__self__, RequestCommitPort)
        source = load_history(source_publication)
        assert source == next(entry for entry in history['items']
                              if entry['publication_id'] == source_publication)
        observed.append(source)
        resolve(entries, bundle, load_boundary=load_boundary, load_history=load_history)
        raise CommandError('authenticated history callback captured', kind='history_unavailable')

    monkeypatch.setattr(_commit_patch, 'inverse_address_resolver', capture)
    call = {'schema_version': 1, 'op': 'timeline.inverse', 'version': '1',
            'select': None, 'args': {'publications': [source_publication]}}
    body = {**request, 'base_revision_id': head['revision_id'],
            'base_publication_id': head['publication_id'], 'commands': [call], 'label': 'undo',
            'dry_run': True, 'steps': [{'id': 'undo', 'label': 'undo', 'intent': 'Reverse steps',
            'tags': [], 'command_ordinals': [0], 'patch': [], 'reads': []}]}
    with pytest.raises(RuntimeErrorBase, match='authenticated history callback captured'):
        send(project, 't', body, idempotency_key='lookup-preview')
    assert len(observed) == 1
    assert dump(tmp_path) == before
    assert document('t') == canonical
    assert client.timelines.history(project, 't', limit=100).data == history


@pytest.mark.parametrize('mutation', [
    'missing-lookup', 'wrong-publication', 'renamed-source-step', 'source-ordinal-range',
    'source-ordinal-order', 'shifted-native-partition', 'swapped-valid-identities',
])
def test_inherited_identity_requires_original_history_partition(captured, mutation):
    history = captured['before']['history']['items']
    entry = history[-1]
    stages = [binding['boundary'] for binding in entry['records']['commands'][0]['bindings']
              if binding['key'] == 'inverse.stage']
    source = next(item for item in history if item['publication_id'] == stages[0]['publication_id'])
    if mutation == 'renamed-source-step':
        source['records']['steps'][1]['id'] = 'other-original-step'
    elif mutation == 'source-ordinal-range':
        source['records']['steps'][1]['command_ordinals'] = [len(source['records']['commands'])]
    elif mutation == 'source-ordinal-order':
        source['records']['steps'].reverse()
    elif mutation == 'shifted-native-partition':
        stages[0]['native_write_range'][1] = 2
        stages[1]['native_write_range'][0] = 2
    elif mutation == 'swapped-valid-identities':
        for key in ('step_id', 'command_ordinals'):
            stages[0][key], stages[1][key] = stages[1][key], stages[0][key]
    bundle = bundle_from_document(captured['before']['document'])
    snapshot = copy.deepcopy((captured, bundle))
    lookups = []

    def lookup(publication):
        lookups.append(publication)
        return {**source, 'publication_id': 'other-publication'} if mutation == 'wrong-publication' else source

    def boundary(entry):
        pytest.fail('inherited identity must be checked before loading execution boundaries')

    with pytest.raises(CommandError):
        inverse_address_resolver([entry], bundle, load_boundary=boundary,
                                 load_history=None if mutation == 'missing-lookup' else lookup)
    assert (captured, bundle) == snapshot
    assert lookups == ([] if mutation == 'missing-lookup' else [source['publication_id']])
